"use client";

import Link from "next/link";
import { usePathname } from "next/navigation";
import {
  LayoutDashboard,
  ShieldCheck,
  MessageSquare,
  Gavel,
  BarChart3,
  LogOut,
} from "lucide-react";
import { session } from "../lib/api";

const navigation = [
  {
    label: "Dashboard",
    href: "/",
    icon: LayoutDashboard,
  },
  {
    label: "KYC Management",
    href: "/kyc",
    icon: ShieldCheck,
  },
  {
    label: "Client Queries",
    href: "/queries",
    icon: MessageSquare,
  },
  {
    label: "Resolution Centre",
    href: "/resolutions",
    icon: Gavel,
  },
  {
    label: "Reports",
    href: "/reports",
    icon: BarChart3,
  },
];

export default function AdminSidebar() {
  const pathname = usePathname();

  function logout() {
    session.clear();
    window.location.href = "/login";
  }

  return (
    <aside className="fixed inset-y-0 left-0 z-40 hidden w-64 flex-col bg-[#082d16] text-white lg:flex">
      {/* Brand */}
      <div className="flex h-20 items-center border-b border-white/10 px-6">
        <div>
          <div className="text-2xl font-extrabold tracking-tight">
            Oak<span className="text-[#f5c400]">Pay</span>
          </div>

          <div className="mt-0.5 text-[10px] font-bold uppercase tracking-[0.18em] text-white/45">
            Operations Admin
          </div>
        </div>
      </div>

      {/* Navigation */}
      <div className="px-4 pt-6">
        <p className="px-3 pb-3 text-[10px] font-bold uppercase tracking-[0.16em] text-white/35">
          Operations
        </p>
      </div>

      <nav className="flex-1 space-y-1 px-3">
        {navigation.map((item) => {
          const Icon = item.icon;

          const active =
            item.href === "/"
              ? pathname === "/"
              : pathname === item.href ||
                pathname.startsWith(`${item.href}/`);

          return (
            <Link
              key={item.href}
              href={item.href}
              className={[
                "group flex items-center gap-3 rounded-xl px-4 py-3 text-sm font-semibold transition-all",
                active
                  ? "bg-[#397b0a] text-white shadow-lg shadow-black/10"
                  : "text-white/65 hover:bg-white/8 hover:text-white",
              ].join(" ")}
            >
              <Icon
                size={19}
                strokeWidth={active ? 2.2 : 1.8}
                className={
                  active
                    ? "text-[#f5c400]"
                    : "text-white/45 group-hover:text-white"
                }
              />

              <span>{item.label}</span>
            </Link>
          );
        })}
      </nav>

      {/* Account */}
      <div className="border-t border-white/10 p-4">
        <button
          type="button"
          onClick={logout}
          className="flex w-full items-center gap-3 rounded-xl px-4 py-3 text-sm font-semibold text-white/55 transition hover:bg-white/10 hover:text-white"
        >
          <LogOut size={18} />
          Sign out
        </button>
      </div>
    </aside>
  );
}